account_balance = 0

def manage_account():
    """Manage a bank account based on user input."""

    while True:
        action = input("Enter 'deposit', 'withdraw', or 'balance' to proceed: ").lower()

        if action in ['deposit', 'balance']:
            # Handle deposit and balance actions
            if action == 'deposit':
                deposit_amount = float(input("Enter the amount to deposit: $"))
                account_balance += deposit_amount
                print(f"Account balance after deposit: ${account_balance:.2f}")
            elif action == 'balance':
                print(f"Account balance: ${account_balance:.2f}")

        elif action in ['withdraw', 'quit']:
            # Handle withdraw and quit actions
            if action == 'withdraw':
                withdraw_amount = float(input("Enter the amount to withdraw: $"))
                if withdraw_amount > account_balance:
                    print("Insufficient funds. Cannot withdraw.")
                else:
                    account_balance -= withdraw_amount
                    print(f"Account balance after withdrawal: ${account_balance:.2f}")
                    break
            elif action == 'quit':
                print("Goodbye!")
                break

            else:
                print("Invalid action. Please try again.")

        else:
            print("Invalid action. Please try again.")

        # Keep asking for user input until they enter 'quit'

manage_account()
